%% Initialize% do initialize first in main.mclear %clc%tmp = matlab.desktop.editor.getActive;%cd(fileparts(tmp.Filename));%% 単機牽引用の変数clearsyms p1 p2 p3 dp1 dp2 dp3 q0 q1 q2 q3 o1 o2 o3 realsyms u1 u2 u3 u4 realsyms R realsyms m l jx jy jz gravity km1 km2 km3 km4 k1 k2 k3 k4 Lx Ly lx ly lz rotor_r cableL realsyms mL real % syms ax ay dax day reale3 = [0; 0; 1];q  = [q0; q1; q2; q3];                   % クォータニオンob = [o1; o2; o3];                       % 機体角速度xQ = [p1; p2; p3];                       % 機体位置vQ = [dp1; dp2; dp3];                    % 機体速度alpha  = [ax; ay];                      % 揺れ角dalpha = [dax; day];                    % 揺れ角速度[Rb0,L] = RodriguesQuaternion(q);   % Rotation matrixU = [u1;u2;u3;u4];                  % Thrust force ：正がzb 向き%オイラー角をクオータニオンに変換syms roll pitch yaw droll dpitch dyaw realEq0 = cos(roll/2)*cos(pitch/2)*cos(yaw/2) + sin(roll/2)*sin(pitch/2)*sin(yaw/2);Eq1 = sin(roll/2)*cos(pitch/2)*cos(yaw/2) - cos(roll/2)*sin(pitch/2)*sin(yaw/2);Eq2 = cos(roll/2)*sin(pitch/2)*cos(yaw/2) + sin(roll/2)*cos(pitch/2)*sin(yaw/2);Eq3 = cos(roll/2)*cos(pitch/2)*sin(yaw/2) - sin(roll/2)*sin(pitch/2)*cos(yaw/2);Eq = [Eq0;Eq1;Eq2;Eq3];[ERb0,EL] = RodriguesQuaternion(Eq) ;Ib = diag([jx, jy, jz]);dq = L' * ob / 2;                        % クォータニオン微分% 単位方向ベクトル p(alpha) とその微分p_alpha = [cos(ax)*sin(ay);           sin(ax);           cos(ax)*cos(ay)];Jp = jacobian(p_alpha, alpha);            % ヤコビ行列dp_alpha = Jp * dalpha;                  % p_dotp_drift_ddot = simplify(jacobian(dp_alpha, alpha) * dalpha); % p_drift_ddot (dalphaの2次項)% 揺れ角ダイナミクス f_alpha, B_alphaf_alpha = [-gravity/cableL * sin(ax)*cos(ay) - day^2 * sin(ax)*cos(ax);           -gravity/(cableL*cos(ax)) * sin(ay) + 2*dax*day * tan(ax)];B_alpha = [ 1/cableL * sin(ax)*sin(ay),      -1/cableL * cos(ax), 1/cableL * sin(ax)*cos(ay);           -1/(cableL*cos(ax)) * cos(ay),    0,                   1/(cableL*cos(ax)) * sin(ay)];%% 1. With load model (標準モデル)physicalParam = {m, Lx, Ly, lx, ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4, rotor_r, mL, cableL};ddxQ    = [0;0;gravity] - (mL*cableL)/(m + mL)*p_drift_ddot - (1/(m + mL))*u1*Rb0*e3;ddalpha = f_alpha - (1/(m*cableL)) * B_alpha * (u1*Rb0*e3);dob     = inv(Ib) * cross(-ob, Ib*ob) + inv(Ib) * [u2; u3; u4];% 17次元状態量 x = [xQ; alpha; vQ; dalpha; q; ob]x = [xQ; alpha; vQ; dalpha; q; ob];f = [vQ; dalpha; ddxQ; ddalpha; dq; dob];Fl = subs(f, U, [0; 0; 0; 0]);Gl = [subs(subs(f, [u2;u3;u4], [0;0;0]), u1, 1) - Fl, ...      subs(subs(f, [u1;u3;u4], [0;0;0]), u2, 1) - Fl, ...      subs(subs(f, [u1;u2;u4], [0;0;0]), u3, 1) - Fl, ...      subs(subs(f, [u1;u2;u3], [0;0;0]), u4, 1) - Fl];simplify(f - (Fl + Gl * U)) % 0 になるか検証matlabFunction_with_input_order(Fl, 'file', 'FL_alpha', ...    'vars', {x, cell2sym(physicalParam)}, 'outputs', {'dxf'});matlabFunction_with_input_order(Gl, 'file', 'GL_alpha', ...    'vars', {x, cell2sym(physicalParam)}, 'outputs', {'dxg'});%% 2. 質量推定 + x,y外乱込みモデル (コントローラ設計用)syms dstx dsty realphysicalParamDst = {m, Lx, Ly, lx, ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4, rotor_r, mL, cableL, dstx, dsty};ddxQ_dst = ddxQ + [dstx; dsty; 0]; % 外乱の付加f_dst    = [vQ; dalpha; ddxQ_dst; ddalpha; dq; dob];Fl_dst = subs(f_dst, U, [0; 0; 0; 0]);Gl_dst = [subs(subs(f_dst, [u2;u3;u4], [0;0;0]), u1, 1) - Fl_dst, ...          subs(subs(f_dst, [u1;u3;u4], [0;0;0]), u2, 1) - Fl_dst, ...          subs(subs(f_dst, [u1;u2;u4], [0;0;0]), u3, 1) - Fl_dst, ...          subs(subs(f_dst, [u1;u2;u3], [0;0;0]), u4, 1) - Fl_dst];simplify(f_dst - (Fl_dst + Gl_dst * U)) % 0 になるか検証matlabFunction_with_input_order(Fl_dst, 'file', 'FLxyDst_alpha', ...    'vars', {x, cell2sym(physicalParamDst)}, 'outputs', {'dxf'});matlabFunction_with_input_order(Gl_dst, 'file', 'GLxyDst_alpha', ...    'vars', {x, cell2sym(physicalParamDst)}, 'outputs', {'dxg'});%% Local functionsfunction m = Mtake(mat,m,n)    m = mat(m,n);end